import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive; covers 31 May inclusive

log_lines = []


def log(msg):
    print(msg, file=sys.stderr, flush=True)
    log_lines.append(msg)


def request(method, path, token=None):
    """Perform a request, retrying on rate limit / server errors. Returns (status, body_text, headers)."""
    attempts = 0
    while True:
        attempts += 1
        headers = {}
        if token:
            headers["Authorization"] = f"Bearer {token}"
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.read().decode("utf-8"), resp.headers
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="replace")
            status = e.code
            hdrs = e.headers
            if status == 429:
                wait = hdrs.get("Retry-After")
                if wait is None:
                    try:
                        wait = json.loads(body).get("retry_after")
                    except Exception:
                        wait = None
                log(f"429 on {method} {path}: body={body[:300]!r} retry_after={wait!r} "
                    f"headers={dict(hdrs)}")
                try:
                    secs = float(wait)
                except (TypeError, ValueError):
                    secs = 5.0
                time.sleep(secs + 0.5)
                continue
            if status >= 500:
                log(f"{status} on {method} {path}: {body[:300]!r}; retrying")
                time.sleep(min(2 * attempts, 30))
                continue
            return status, body, hdrs
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            log(f"network error on {method} {path}: {e!r}; retrying")
            time.sleep(min(2 * attempts, 30))


class Client:
    def __init__(self):
        self.token = None
        self.refresh_token()

    def refresh_token(self):
        status, body, _ = request("POST", "/token")
        if status != 200:
            raise RuntimeError(f"token request failed: {status} {body[:300]}")
        self.token = json.loads(body)["token"]
        log(f"got token {self.token}")

    def get_authed(self, path):
        """GET with auth; refresh token on 401 and retry the same request."""
        for _ in range(20):
            status, body, hdrs = request("GET", path, self.token)
            if status == 401 or status == 403:
                log(f"{status} on {path}: {body[:200]!r}; refreshing token")
                self.refresh_token()
                continue
            return status, body
        raise RuntimeError(f"gave up on {path} after repeated auth failures")


