    orders_raw = []
    pages_seen = []
    path = "/orders?page=1"
    while path:
        status, body = client.get_authed(path)
        if status != 200:
            raise RuntimeError(f"unexpected {status} on {path}: {body[:300]}")
        data = json.loads(body)
        pages_seen.append(data["page"])
