        orders_raw.extend(data["items"])
        path = data["next"]

    log(f"pages fetched: {pages_seen}")
    log(f"raw listing rows: {len(orders_raw)}")

    # Dedupe by id, noting any repeats and whether they differ.
    by_id = {}
    duplicates_skipped = 0
    conflicting_dupes = []
    for o in orders_raw:
        oid = o["id"]
