    customers = {}
    missing_customers = []
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    for o in qualifying:
        cid = o["customer_id"]
        if cid not in customers:
            status, body = client.get_authed(f"/customers/{cid}")
            if status == 404:
                missing_customers.append(cid)
                customers[cid] = None
            elif status == 200:
                customers[cid] = json.loads(body)
            else:
                raise RuntimeError(f"unexpected {status} on /customers/{cid}: {body[:300]}")
        c = customers[cid]
        if c is None:
            continue
        pct = c["discount_pct"]
        if not isinstance(pct, int):
            raise RuntimeError(f"non-integer discount_pct for {cid}: {pct!r}")
        amount = o["amount_cents"]
        if not isinstance(amount, int):
            raise RuntimeError(f"non-integer amount_cents for {o['id']}: {amount!r}")
        # Round half up per order: amount * (100 - pct) / 100, exact via Decimal.
        discounted = (Decimal(amount) * Decimal(100 - pct) / Decimal(100)).quantize(
            Decimal(1), rounding=ROUND_HALF_UP
        )
        discounted = int(discounted)
        total += discounted
        by_region[c["region"]] += discounted

    log(f"customers looked up: {len(customers)}; missing (404): {missing_customers}")
    log(f"discount/offset formats seen: {sorted(tz_offsets)}")

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))
    return result


if __name__ == "__main__":
    main()

